function addLab(id,title,type,description,controls,compute,terms){const engine={id,title,type,description,controls,compute:v=>{const r=withCalculation(()=>compute(v),id,v);if(r.calculation)r.calculation.symbols=controls.map(c=>[c.id,c.label]);return r},terms:terms.split('|').filter(Boolean)};labEngines.push(engine);for(const name of engine.terms)labTermMap[name]=id;return engine}
const LN=LC.n,LS=LC.s,LT=LC.t,LB=LC.c;
const lmean=a=>a.reduce((s,x)=>s+x,0)/a.length,lvar=a=>lmean(a.map(x=>(x-lmean(a))**2)),lsig=x=>1/(1+Math.exp(-x));
function lnums(text){const a=String(text).split(/[,，\s]+/).filter(Boolean).map(Number);if(!a.length||a.some(x=>!Number.isFinite(x)))throw Error('請輸入以逗號或空白分隔的有限數值。');if(a.length>200)throw Error('教學範例最多使用200個數值。');return a}
function lsoftmax(a,t=1){const m=Math.max(...a),e=a.map(x=>Math.exp((x-m)/t)),s=e.reduce((a,b)=>a+b,0);return e.map(x=>x/s)}
function ldot(a,b){return a.reduce((s,x,i)=>s+x*b[i],0)}
